import{_ as a,o as t,c as i,a3 as s}from"./chunks/framework.DQ-7HQaQ.js";const u=JSON.parse('{"title":"Clean builds and release evidence","description":"","frontmatter":{},"headers":[],"relativePath":"engineering/clean-build.md","filePath":"engineering/clean-build.md","lastUpdated":1794374806000}'),n={name:"engineering/clean-build.md"};function r(o,e,l,d,p,c){return t(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="clean-builds-and-release-evidence" tabindex="-1">Clean builds and release evidence <a class="header-anchor" href="#clean-builds-and-release-evidence" aria-label="Permalink to &quot;Clean builds and release evidence&quot;">​</a></h1><p>There are two distinct deliverables: the documentation site that exists now, and the application planned here. Their commands, test results and deployment claims must not be mixed.</p><h2 id="documentation-runnable-now" tabindex="-1">Documentation: runnable now <a class="header-anchor" href="#documentation-runnable-now" aria-label="Permalink to &quot;Documentation: runnable now&quot;">​</a></h2><p>From a clean checkout with Node.js 22 or newer:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ci</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/examples/stream.test.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/examples/publication.py</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check-plan.mjs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/check-pages.mjs</span></span></code></pre></div><p>The lease example uses an explicitly selected Rust compiler in CI:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> toolchain</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.90.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minimal</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rustc</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +1.90.0</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --edition=2021</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs/examples/lease.rs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/ordo-lease-tests</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/tmp/ordo-lease-tests</span></span></code></pre></div><p>This compiler pin applies to a dependency-free documentation exercise, not a decision about the future runtime&#39;s supported toolchain. The application toolchain must be selected and security-reviewed at its own setup gate. The examples use synthetic data, no model credentials, no private donor checkout and no external service calls.</p><p>The site build checks Markdown links; the repository checker also checks generated targets, the repository subpath and sitemap. These checks do not prove responsive design, keyboard access, real browser streaming or live Pages publication.</p><h2 id="application-proposed-commands-not-available-yet" tabindex="-1">Application: proposed commands, not available yet <a class="header-anchor" href="#application-proposed-commands-not-available-yet" aria-label="Permalink to &quot;Application: proposed commands, not available yet&quot;">​</a></h2><p>The future workspace should expose a small process/administration interface, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lab api       # stateless public HTTP/SSE service</span></span>
<span class="line"><span>lab store     # private transaction owner and attached durable state</span></span>
<span class="line"><span>lab worker    # bounded capability execution</span></span>
<span class="line"><span>lab admin     # scoped migration, import, export, verify or repair</span></span>
<span class="line"><span>lab local     # explicit embedded-store authoring profile</span></span></code></pre></div><p>These names are design examples. Running them in the present docs-only repository will not start an application.</p><p>Before implementation, pin the Rust toolchain and commit <code>Cargo.lock</code>; pin frontend dependencies and commit its lockfile. Declare ffmpeg/ffprobe and other external tools separately from Cargo dependencies. Each model manifest needs weights, tokenizer/preprocessing identity, dimensions where relevant, license/distribution policy and content hashes. A model name without an immutable identity is insufficient replay evidence.</p><p>For Rust builds, <code>--locked</code> requires the lockfile to remain unchanged; <code>--frozen</code> additionally requires offline operation. An offline build needs an intentionally prepared dependency cache or vendor source. Neither flag alone proves bit-for-bit reproducibility. <a href="https://doc.rust-lang.org/cargo/commands/cargo-build.html" target="_blank" rel="noreferrer">Cargo build options</a>.</p><h2 id="build-→-release-→-run" tabindex="-1">Build → release → run <a class="header-anchor" href="#build-→-release-→-run" aria-label="Permalink to &quot;Build → release → run&quot;">​</a></h2><p><strong>Build:</strong> verify source and dependency inputs, run unit/contract/integration tests, compile frontend and Rust binaries, produce a versioned image per supported architecture, record SBOM and scan results, then identify artifacts by digest.</p><p><strong>Release:</strong> combine an approved artifact with deployment configuration, schema compatibility, the published library revision and capability/model manifests. Validate migrations on a disposable copy and bind QA acceptance to that exact selection. Record a rollback or forward-repair procedure.</p><p><strong>Run:</strong> start the existing artifact. Do not install packages, compile source, download an unpinned model or migrate implicitly on every web-process startup. Readiness should report whether required storage/schema/capabilities are compatible without leaking credentials.</p><p>A failed release leaves the previous selection intact. Library publication and software deployment are separately versioned operations: updating the UI must not silently rewrite research evidence.</p><h2 id="required-evidence-before-a-hosted-release" tabindex="-1">Required evidence before a hosted release <a class="header-anchor" href="#required-evidence-before-a-hosted-release" aria-label="Permalink to &quot;Required evidence before a hosted release&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Evidence</th><th>What it establishes</th><th>What it does not establish</th></tr></thead><tbody><tr><td>Locked clean build</td><td>Declared inputs can produce the artifact in that build environment</td><td>Universal bit-identical output on every platform</td></tr><tr><td>Unit and contract tests</td><td>Covered rules hold for their fixtures</td><td>Production authorization or capacity by themselves</td></tr><tr><td>SQLite integration tests</td><td>Transaction/constraint behavior on the selected engine</td><td>Correct remote filesystem behavior or distributed writer support</td></tr><tr><td>Fault injection</td><td>Covered shutdown, replay and publication failures recover as designed</td><td>Every possible hardware fault</td></tr><tr><td>Proxy/browser tests</td><td>Real framing, cancellation, session isolation and citations through HTTPS</td><td>Long-term service availability</td></tr><tr><td>Restore rehearsal</td><td>Selected backup restores into an isolated compatible environment</td><td>That an untested provider snapshot is application-consistent</td></tr><tr><td>Retrieval evaluation</td><td>Quality on a fixed reviewed set, including false matches</td><td>A universal confidence threshold</td></tr></tbody></table><h2 id="platform-matrix" tabindex="-1">Platform matrix <a class="header-anchor" href="#platform-matrix" aria-label="Permalink to &quot;Platform matrix&quot;">​</a></h2><p>Use Linux QA with the production storage engine and deployment configuration shape. Test macOS authoring/export separately. Both consume the same schema/contract fixtures; the macOS run also tests missing-capability behavior when reopening its output on Linux.</p><p>Native acceleration is a separately qualified backend. Keep CPU/deterministic fixtures for protocol tests, but evaluate real embedding and media quality independently. Never replace an embedding model with a different model merely because the vector dimensions match.</p><h2 id="review-and-public-data-boundaries" tabindex="-1">Review and public-data boundaries <a class="header-anchor" href="#review-and-public-data-boundaries" aria-label="Permalink to &quot;Review and public-data boundaries&quot;">​</a></h2><p>Public examples contain synthetic data only. Public exports must be physically constructed from approved records and objects; a full database with hidden UI filters is not a public-safe export. Search indexes, deleted-page remnants, logs and manifests can also contain private content. Test export contents, not just the visible web page.</p><p>A clean checkout must not require the owner&#39;s <code>.env</code>, local home paths or private source repository. Imported source carries its provenance and applicable notices. The <a href="./../reuse/harvest-plan">harvest checklist</a> is part of the build gate, not optional housekeeping.</p>`,28)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
